-- Тема 06: правки по отчёту Codex (26 исправлений в 12 вопросах), ключи не меняются.
-- Источник: scripts/questions/094_codex_topic06_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Что верно для команды VACUUM FULL?', NULL, NULL, NULL, 'Что верно для команды VACUUM FULL на разросшейся таблице?'),
        ('question', 'Как PostgreSQL собирает статистику для планировщика?', NULL, NULL, NULL, 'Как ANALYZE собирает статистику по большой таблице?'),
        ('question', 'К чему приводит отключение автоочистки, если не выполнять очистку и анализ вручную?', NULL, NULL, NULL, 'К чему со временем приводит отключение автоочистки при регулярных изменениях данных, если не выполнять очистку и анализ вручную?'),
        ('question', 'Что блокирует команда REINDEX?', NULL, NULL, NULL, 'Что блокирует команда REINDEX INDEX без CONCURRENTLY?'),
        ('question', 'Что отмечается в карте свободного пространства индекса?', NULL, NULL, NULL, 'Что отмечается в карте свободного пространства индекса B-дерева?'),
        ('question', 'Почему индекс-B-дерево не уменьшается даже после удаления большинства записей?', NULL, NULL, NULL, 'Почему файл индекса B-дерева не уменьшается, даже когда очистка уже убрала ссылки на большинство записей?'),
        ('question', 'Возвращает ли обычный VACUUM освободившееся место операционной системе?', NULL, NULL, NULL, 'Возвращает ли обычный VACUUM, как правило, освободившееся место операционной системе?'),
        ('option', 'Что верно для команды VACUUM FULL на разросшейся таблице?', 'Собирает статистику для планировщика', 'Собирает статистику распределения значений', 'Статистику собирает ANALYZE.', 'Её собирает ANALYZE. VACUUM FULL обновляет в pg_class лишь размер таблицы и число строк.'),
        ('option', 'Как ANALYZE собирает статистику по большой таблице?', 'Полным чтением всех строк таблицы', NULL, 'На больших таблицах это слишком долго, а точная статистика и не нужна.', 'Небольшую таблицу ANALYZE может прочитать целиком, но большую читать полностью слишком долго, а точная статистика и не нужна.'),
        ('option', 'Как карта видимости ускоряет доступ только по индексу?', 'Отмечает пустые страницы индекса для пропуска', NULL, 'Это делает карта свободного пространства индекса.', 'Пустые страницы индекса отмечает карта свободного пространства, и нужны они для повторного использования, а не для пропуска при сканировании.'),
        ('option', 'Как карта видимости ускоряет доступ только по индексу?', 'Видимость отмеченных страниц не проверяется по таблице', 'Видимость на отмеченных страницах ясна без таблицы', NULL, NULL),
        ('explanation', 'Как карта видимости ускоряет доступ только по индексу?', NULL, NULL, 'Если страница отмечена all-visible, индексному сканированию не нужно обращаться к таблице для проверки видимости найденной версии.', 'При доступе только по индексу: если страница отмечена all-visible, сканированию не нужно обращаться к таблице для проверки видимости найденной версии.'),
        ('option', 'Что означает, что версия строки заморожена?', 'Создавшая её транзакция считается давно завершённой', 'Создавшая её транзакция — в прошлом для всех снимков', NULL, NULL),
        ('option', 'Что означает, что версия строки заморожена?', 'Она отмечена как мёртвая и ждёт удаления при очистке', NULL, 'Удаления ждут мёртвые версии, а не замороженные.', 'Заморозка сама по себе не делает версию мёртвой: мёртвой её сделает удаление или обновление строки.'),
        ('option', 'К чему со временем приводит отключение автоочистки при регулярных изменениях данных, если не выполнять очистку и анализ вручную?', 'К ускорению запросов за счёт экономии ввода-вывода', 'К отключению записи изменений таблиц в журнал', 'Кажущаяся экономия ввода-вывода оборачивается гораздо худшими последствиями.', 'Журналирование от автоочистки не зависит.'),
        ('option', 'К чему со временем приводит отключение автоочистки при регулярных изменениях данных, если не выполнять очистку и анализ вручную?', 'К неконтролируемому разрастанию таблиц и индексов', NULL, 'Мёртвые версии накапливаются: при обычной работе вычищается лишь малая их часть.', 'Мёртвые версии накапливаются: очистка внутри страниц при обычной работе убирает лишь часть их.'),
        ('option', 'Чем автоочистка лучше очистки по расписанию?', 'Обрабатывает таблицы чаще там, где больше изменений', NULL, 'Автоочистка реагирует на активность изменений; расписание либо создаёт лишнюю нагрузку, либо не успевает за изменениями.', 'Автоочистка реагирует на накопленные изменения и пороги. Фиксированное расписание легко подобрать неудачно: лишняя работа или отставание от всплесков нагрузки.'),
        ('option', 'Чем автоочистка лучше очистки по расписанию?', 'Возвращает освободившееся место операционной системе', NULL, 'Обычная очистка место ОС, как правило, не возвращает.', 'Обычная очистка место ОС, как правило, не возвращает. Отсечь пустой хвост файла может и ручная, и автоматическая очистка, так что это не преимущество автоочистки.'),
        ('option', 'Что блокирует команда REINDEX INDEX без CONCURRENTLY?', 'Ничего: индекс перестраивается рядом со старым', NULL, 'Без блокировки изменений работает REINDEX CONCURRENTLY, а обычный REINDEX блокирует запись.', 'REINDEX CONCURRENTLY допускает изменения строк, хотя тоже берёт блокировки; обычный REINDEX блокирует запись.'),
        ('option', 'Что блокирует команда REINDEX INDEX без CONCURRENTLY?', 'Все таблицы базы данных на время работы', NULL, 'Блокировки касаются только таблицы и её индекса.', 'REINDEX INDEX блокирует только таблицу этого индекса и сам индекс.'),
        ('option', 'Что отмечается в карте свободного пространства индекса B-дерева?', 'Ничего: у индексов нет карты свободного пространства', 'Ничего: у B-дерева нет карты свободного пространства', 'У индексов нет карты видимости, а карта свободного пространства у них есть (например, у B-деревьев).', 'У B-дерева карта свободного пространства есть. Карты видимости у индексов нет, а у hash-индексов нет и карты свободного пространства.'),
        ('option', 'Почему файл индекса B-дерева не уменьшается, даже когда очистка уже убрала ссылки на большинство записей?', 'Очистка не убирает из индексов мёртвые ссылки', NULL, 'Очистка убирает из индексов ссылки на мёртвые версии строк.', 'По условию ссылки уже убраны, а само их удаление файл индекса не уменьшает.'),
        ('option', 'Возвращает ли обычный VACUUM, как правило, освободившееся место операционной системе?', 'Как правило, нет: место остаётся для новых версий', 'Нет: место остаётся для новых версий строк', NULL, NULL),
        ('option', 'Чем VACUUM FULL отличается от обычного VACUUM?', 'Перезаписывает таблицу и индексы под исключительной блокировкой', 'Переписывает таблицу, блокируя чтение и запись', 'Таблица на это время недоступна даже для чтения.', 'Таблица и индексы строятся заново, на это время таблица недоступна даже для чтения.'),
        ('option', 'Какое ограничение есть у REINDEX ... CONCURRENTLY?', 'Нельзя запускать внутри блока транзакции BEGIN … COMMIT', 'Нельзя запускать внутри блока транзакции', NULL, NULL),
        ('option', 'Какое ограничение есть у REINDEX ... CONCURRENTLY?', 'Выполняется быстрее, чем обычный REINDEX того же индекса', 'Не может перестроить уникальный индекс', 'Обычно работает дольше обычного REINDEX: индекс строится в несколько проходов.', 'Уникальные индексы так перестраивать можно; ограничения касаются блока транзакции, индексов системного каталога и ограничений-исключений.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
